-- Create FlaggedImages table manually
CREATE TABLE IF NOT EXISTS "FlaggedImages" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ImageHash" character varying(256) NOT NULL,
    "FileName" character varying(500) NOT NULL,
    "StoragePath" character varying(1000) NOT NULL,
    "CueId" integer,
    "CueCaseId" integer,
    "UserId" integer NOT NULL,
    "FlagReason" character varying(50) NOT NULL DEFAULT 'other',
    "AIConfidenceScore" double precision,
    "IsAIFlagged" boolean NOT NULL DEFAULT TRUE,
    "Status" character varying(20) NOT NULL DEFAULT 'pending',
    "AdminNotes" text,
    "AdminUserId" integer,
    "FlaggedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "ReviewedAt" timestamp with time zone,
    CONSTRAINT "PK_FlaggedImages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FlaggedImages_Users_AdminUserId" FOREIGN KEY ("AdminUserId") REFERENCES "Users"("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_FlaggedImages_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users"("Id") ON DELETE RESTRICT
);

-- Create ModerationQueues table manually
CREATE TABLE IF NOT EXISTS "ModerationQueues" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "FlaggedImageId" integer NOT NULL,
    "Priority" integer NOT NULL DEFAULT 2,
    "UserReportCount" integer NOT NULL DEFAULT 0,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "ProcessedAt" timestamp with time zone,
    CONSTRAINT "PK_ModerationQueues" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ModerationQueues_FlaggedImages_FlaggedImageId" FOREIGN KEY ("FlaggedImageId") REFERENCES "FlaggedImages"("Id") ON DELETE CASCADE
);

-- Create UserReports table manually
CREATE TABLE IF NOT EXISTS "UserReports" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "FlaggedImageId" integer NOT NULL,
    "ReportingUserId" integer NOT NULL,
    "ReportReason" character varying(255),
    "ReportedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    CONSTRAINT "PK_UserReports" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserReports_FlaggedImages_FlaggedImageId" FOREIGN KEY ("FlaggedImageId") REFERENCES "FlaggedImages"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserReports_Users_ReportingUserId" FOREIGN KEY ("ReportingUserId") REFERENCES "Users"("Id") ON DELETE CASCADE
);

-- Create indices
CREATE INDEX IF NOT EXISTS "IX_FlaggedImages_CueCaseId" ON "FlaggedImages"("CueCaseId");
CREATE INDEX IF NOT EXISTS "IX_FlaggedImages_CueId" ON "FlaggedImages"("CueId");
CREATE INDEX IF NOT EXISTS "IX_FlaggedImages_UserId" ON "FlaggedImages"("UserId");
CREATE INDEX IF NOT EXISTS "IX_FlaggedImages_AdminUserId" ON "FlaggedImages"("AdminUserId");
CREATE INDEX IF NOT EXISTS "IX_ModerationQueues_FlaggedImageId" ON "ModerationQueues"("FlaggedImageId");
CREATE INDEX IF NOT EXISTS "IX_UserReports_FlaggedImageId" ON "UserReports"("FlaggedImageId");
CREATE INDEX IF NOT EXISTS "IX_UserReports_ReportingUserId" ON "UserReports"("ReportingUserId");

-- Verify tables exist
SELECT tablename FROM pg_tables WHERE tablename IN ('FlaggedImages', 'ModerationQueues', 'UserReports');
